/// <summary>
///    The <c>METExciseRegisterSOHExceptionDP</c> class is the report data provider class for the Excise Register Stock On hand Exception Report
/// </summary>
[
    SRSReportQueryAttribute(queryStr(METExciseRegisterInventOnhand)),
    SRSReportParameterAttribute(classStr(METExciseRegisterSOHExceptionContract))
]
class METExciseRegisterSOHExceptionDP extends SrsReportDataProviderPreProcessTempDB
{
    METExciseRegisterSOHExceptionTmp        inventOnhandTmp;
    METExciseRegisterSOHExceptionContract   contract;
}

Method.Source:
/// <summary>
/// Fetches data from the <c>InventOnhandTmp</c> temporary table.
/// </summary>
/// <returns>
/// The data from <c>InventOnhandTmp</c> table.
/// </returns>
[
    SRSReportDataSetAttribute(tableStr(METExciseRegisterSOHExceptionTmp))
]
public METExciseRegisterSOHExceptionTmp getinventOnhandTmp()
{
    select  inventOnhandTmp;
    return  inventOnhandTmp;
}

    /// <summary>
    /// Inserts data into a temporary table.
    /// </summary>
    /// <param name="_inventSum">
    /// A table buffer of an <c>InventSum</c> table.
    /// </param>
    /// <param name="_inventDim">
    /// A table buffer of the <c>Inventdim</c> table.
    /// </param>
    /// <param name="_metExciseRegisterEntry">
    /// A table buffer of the <c>METExciseRegisterAvailableQtyView</c> View.
    /// </param>
    private void insertTmpTable(InventSum _inventSum, InventDim _inventDim,METExciseRegisterAvailableQtyView _metExciseRegisterEntry)
    {
        InventIAvailability inventAvailability = InventAvailabilityProvider::findBySumDim(_inventSum, _inventDim).parmInventAvailability();

        inventOnhandTmp.ItemId          = _inventSum.ItemId;
        inventOnhandTmp.AvailPhysical   = inventAvailability.availPhysical();
        inventOnhandTmp.ReservPhysical  = inventAvailability.reservPhysical();
        
        inventOnhandTmp.InventSiteId    = _inventSum.InventSiteId;
        inventOnhandTmp.ItemDescription = _inventSum.itemName();
        inventOnhandTmp.METAvailableQty = _metExciseRegisterEntry.AvailableQuantity;
        inventOnhandTmp.SiteBondNumber  = _metExciseRegisterEntry.SiteBondNumber;
        inventOnhandTmp.ExceptionQty    = inventOnhandTmp.AvailPhysical + inventOnhandTmp.ReservPhysical - inventOnhandTmp.METAvailableQty;

        if(inventOnhandTmp.ExceptionQty != 0 || contract.parmShowDifferenceOnly() == NoYes::No)
        {
            inventOnhandTmp.insert();
        }
    }

    /// <summary>
    /// Processes the report business logic.
    /// </summary>
    /// <remarks>
    /// Provides the ability to write the report business logic. This method will be called by  at runtime.
    /// The method should compute data and populate the data tables that will be returned to .
    /// </remarks>
    public void processReport()
    {
        InventDim   inventDim;

        contract = this.parmDataContract() as METExciseRegisterSOHExceptionContract;
        
        Query query = this.getQuery();

        QueryRun queryRun = new QueryRun(query);
        inventOnhandTmp.setConnection(this.parmUserConnection());
        
        while (queryRun.next())
        {
            InventSum                           inventSum       = queryRun.get(tableNum(InventSum));
            METExciseRegisterAvailableQtyView   exciseRegister  = queryRun.get(tableNum(METExciseRegisterAvailableQtyView));

            if (InventTable::find(inventSum.ItemId).inventItemType().mustInventBeControlled())
            {
                inventDim.inventSiteID = contract.parmSiteId();
            }
            if (!InventTable::find(inventSum.ItemId).inventItemType().isServiceItem())
            {
                this.insertTmpTable(inventSum, inventDim,exciseRegister);
                inventDim.clear();
            }
        }
    }

    private query getQuery()
    {
        Query query = this.parmQuery();
        
        QueryBuildDataSource    qbsSum,qbdMETTariffItemCode;

        qbsSum = query.dataSourceTable(tableNum(InventSum));

        if (contract.parmSiteId())
        {
            QueryBuildRange  queryRangeSite = qbsSum.findRange(fieldNum(InventSum,InventSiteId));
            queryRangeSite.value(contract.parmSiteId());
        }

        if (contract.parmItemId())
        {
            QueryBuildRange  queryRangeItem = qbsSum.findRange(fieldNum(InventSum,ItemId));
            queryRangeItem.value(contract.parmItemId());
        }

        qbdMETTariffItemCode = query.dataSourceTable(tableNum(METTariffItemCode));
        qbdMETTariffItemCode.findRange(fieldNum(METTariffItemCode,CustomsExcise)).value(SysQuery::valueNot(METCustomExcise::Blank));

        return query;
    }
